    {"id":"sh-024","situation":"sacked-season-edition","fits":["sacked-both-draw"],"headline":"SACKED TOGETHER, LEVEL TOGETHER","subhead":"Both managers out and both on {points} points. The Showdown is drawn.","kicker":"FINAL STANDINGS"},
    {"id":"sh-025","situation":"sacked-season-edition","fits":["sacked-both-draw"],"headline":"EVEN THE SACKINGS WERE A DRAW","subhead":"{managerA} and {managerB} finish level on {points} points apiece.","kicker":"IRONY CORNER"}
